export function resolveClientIdentity(input) {
  const socket = normalizeIp(input.socketAddress);
  const peerIsProxy = input.trustedProxies.some((proxy) => normalizeIp(proxy) === socket);
  return peerIsProxy ? normalizeIp(singleHeaderValue(input.headers, input.headerName)) ?? socket : socket;
}

